TLM.f("Sancti/04-28",{"officium":"S. Pauli a Cruce Confessoris","rule":["Evangelium non appropriatum","vide C5"],"fallback":"Commune/C5","from":{"GradualeP":"Commune/C5"},"sections":{"Introitus":[{"k":"ref","la":"Gal 2:19-20"},{"k":"text","la":"Christo confíxus sum Cruci: vivo autem, jam non ego; vivit vero in me Christus: in fide vivo Fílii Dei, qui diléxit me, et trádidit semetípsum pro me, allelúja, alleluja."},{"k":"ref","la":"Ps 40:2"},{"k":"text","la":"Beátus, qui intéllegit super egénum et páuperem: in die mala liberábit eum Dóminus."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Christo confíxus sum Cruci: vivo autem, jam non ego; vivit vero in me Christus: in fide vivo Filii Dei, qui diléxit me, et trádidit semetípsum pro me, allelúja, alleluja."}],"Oratio":[{"k":"text","la":"Dómine Jesu Christe, qui, ad mystérium Crucis prædicándum, sanctum Paulum singulári caritáte donásti, et per eum novam in Ecclésia famíliam floréscere voluísti: ipsíus nobis intercessióne concéde; ut, passiónem tuam júgiter recoléntes in terris, ejúsdem fructum cónsequi mereámur in cœlis:"},{"k":"macro","name":"Qui vivis"}],"Lectio":[{"k":"text","la":"Léctio Epístolæ beáti Pauli Apóstoli ad Corinthios"},{"k":"ref","la":"1 Cor 1:17-25"},{"k":"text","la":"Fratres: Non misit me Christus baptizáre, sed evangelizáre: non in sapiéntia verbi, ut non evacuétur Crux Christi. Verbum enim Crucis pereúntibus quidem stultítia est: iis autem, qui salvi fiunt, id est nobis, Dei virtus est. Scriptum est enim: Perdam sapiéntiam sapiéntium et prudéntiam prudéntium reprobábo. Ubi sápiens? ubi scriba? ubi conquisítor hujus sǽculi? Nonne stultam fecit Deus sapiéntiam hujus mundi? Nam quia in Dei sapiéntia non cognóvit mundus per sapiéntiam Deum: plácuit Deo per stultítiam prædicatiónis salvos fácere credéntes. Quóniam et Judǽi signa petunt et Græci sapiéntiam quærunt: nos autem prædicámus Christum crucifíxum: Judǽis quidem scándalum, géntibus autem stultítiam, ipsis autem vocátis Judǽis atque Græcis Christum Dei virtútem et Dei sapiéntiam: quia, quod stultum est Dei, sapiéntius est homínibus: et, quod infírmum est Dei, fórtius est homínibus."}],"Graduale":[{"k":"text","la":"Allelúja, allelúja."},{"k":"ref","la":"2 Cor 5:15"},{"k":"text","la":"Pro ómnibus mórtuus est Christus: ut, et qui vivunt, jam non sibi vivant, sed ei, qui pro ipsis mórtuus est, et resurréxit. Allelúja."},{"k":"ref","la":"Rom 8:17"},{"k":"text","la":"Si fílii, et herédes: herédes quidem Dei, coherédes autem Christi: si tamen compátimur, ut et conglorificémur. Allelúja."}],"GradualeP":[{"k":"text","la":"Allelúja, allelúja."},{"k":"ref","la":"Jas 1:12"},{"k":"text","la":"Beátus vir, qui suffert tentatiónem: quóniam, cum probátus fúerit, accípiet corónam vitæ. Allelúja."},{"k":"ref","la":"Eccli 45:9"},{"k":"text","la":"Amávit eum Dóminus et ornávit eum: stolam glóriæ índuit eum. Allelúja."}],"Tractus":[{"k":"ref","la":"1 Pet 4:1"},{"k":"text","la":"Christo ígitur passo in carne, et vos eádem cogitatióne armámini: quia, qui passus est in carne, désiit a peccátis."},{"k":"ref","la":"2 Cor 4:10"},{"k":"text","la":"Semper mortificatiónem Jesu in córpore nostro circumferéntes, ut et vita Jesu manifestétur in corpóribus nostris."},{"k":"ref","la":"Heb 12:2"},{"k":"text","la":"Aspiciéntes in auctórem fídei et consummatórem Jesum, qui propósito sibi gáudio sustínuit Crucem, confusióne contémpta, atque in déxtera sedis Dei sedet."}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Lucam"},{"k":"ref","la":"Luc 10:1-9"},{"k":"text","la":"In illo témpore: Designávit Dóminus et álios septuagínta duos: et misit illos binos ante fáciem suam in omnem civitátem et locum, quo erat ipse ventúrus. Et dicebat illis: Messis quidem multa, operárii autem pauci. Rogáte ergo Dóminum messis, ut mittat operários in messem suam. Ite: ecce, ego mitto vos sicut agnos inter lupos. Nolíte portáre sácculum neque peram neque calceaménta; et néminem per viam salutavéritis. In quamcúmque domum intravéritis, primum dícite: Pax huic dómui: et si ibi fúerit fílius pacis, requiéscet super illum pax vestra: sin autem, ad vos revertátur. In eádem autem domo manéte, edéntes et bibéntes quæ apud illos sunt: dignus est enim operárius mercéde sua. Nolíte transíre de domo in domum. Et in quamcúmque civitátem intravéritis, et suscéperint vos, manducáte quæ apponúntur vobis: et curáte infírmos, qui in illa sunt, et dícite illis: Appropinquávit in vos regnum Dei."}],"Offertorium":[{"k":"ref","la":"Ephes 5:2"},{"k":"text","la":"Ambuláte in dilectióne, sicut et Christus diléxit nos, et trádidit semetípsum pro nobis oblatiónem et hóstiam Deo in odórem suavitátis, allelúja."}],"Secreta":[{"k":"text","la":"Cœléstem nobis, Dómine, prǽbeant mystéria hæc passiónis et mortis tuæ fervórem: quo sanctus Paulus, ea offeréndo, corpus suum hóstiam vivéntem, sanctam tibíque placéntem exhíbuit:"},{"k":"macro","name":"Qui vivis"}],"Communio":[{"k":"ref","la":"1 Pet 4:13"},{"k":"text","la":"Communicántes Christi passiónibus gaudéte, ut in revelatióne glóriæ ejus gaudeátis exsultántes. Allelúja."}],"Postcommunio":[{"k":"text","la":"Súmpsimus, Dómine, divínum sacraméntum, imménsæ caritátis tuæ memoriále perpétuum: tríbue, quǽsumus; ut, sancti Pauli méritis et imitatióne, aquam de fóntibus tuis hauriámus in vitam ætérnam saliéntem, et tuam sacratíssimam passiónem córdibus nostris impréssam móribus et vita teneámus:"},{"k":"macro","name":"Qui vivis"}],"Graduale1":[{"k":"ref","la":"Gal 6:14"},{"k":"text","la":"Mihi autem absit gloriári, nisi in Cruce Dómini nostri Jesu Christi: per quem mihi mundus crucifíxus est, et ego mundo."},{"k":"ref","la":"1 Cor 2:2"},{"k":"text","la":"Non judicávi me scire áliquid inter vos, nisi Jesum Christum, et hunc crucifíxum. Allelúja, allelúja."},{"k":"ref","la":"1 Pet 2:21"},{"k":"text","la":"Christus passus est pro nobis, vobis relínquens exémplum, ut sequámini vestígia ejus. Allelúja."}]},"hr":{"8e47a7bb679e115f":{"t":"Gal 2, 19-20, Ps 40, 2\n(Gal 2, 19-20) S Kristom sam na križ razapet. Živim ja, ali to više nisam ja, nego živi u meni Krist. Živim od vjere u Sina Božjega koji me je ljubio i predao sebe za mene, <i>aleluja</i>, <i>aleluja</i>.\n(Ps 40, 2) Blago onom koji razumije siromaha i uboga, u zao dan izbavit će ga Gospodin.\n<i>Slava Ocu, i Sinu, i Duhu Svetomu. Kako bijaše na početku, tako i sada i vazda i u vijeke vjekova. Amen</i>.\n(Gal 2, 19-20) S Kristom sam na križ razapet. Živim ja, ali to više nisam ja, nego živi u meni Krist. Živim od vjere u Sina Božjega koji me je ljubio i predao sebe za mene, <i>aleluja</i>, <i>aleluja</i>.","kn":"(Gal. 2, 19, 20). S Kristom sam razapet na križu i ne živim više ja, nego u meni živi Krist. U vjeri živim Sina Božjega, koji me je ljubio i predao samoga sebe za mene, aleluja, aleluja. (Ps. 40, 2) Blago onome, koji razumije siromaha i ubogoga, u dan zao izbavit će ga Gospodin. Slava Ocu . . . S Kristom . . .","knRef":"Kniewald 1942, str. 554–555 (snimka 278) (OCR)"},"8b02f7f7216c000c":{"t":"<i>Pomolimo se</i>.\nBože, koji si svetoga Pavla obdario posebnom ljubavlju za propovijedanje tajne križa, i htio da po njemu procvjeta nova obitelj u Crkvi, daj nam po njegovu zagovoru da sjećajući se neprestano tvoje muke na zemlji zavrijedimo postići njezin plod na nebu:\n<i>koji živiš i kraljuješ s Bogom Ocem u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Gospodine Isuse Kriste, koji si sv. Pavlu darovao posebnu ljubav, da uzmogne propovijedati tajnu svetoga križa, i koji si htio, da po njemu u Tvojoj Crkvi procvate nova redovnička družba, dopusti nam, njegovirn zagovorom, da vazda se spominjući Tvoje muke na zemlji zaslužimo dostići njezine plodove na nebu, po G. n.","knRef":"Kniewald 1942, str. 554–555 (snimka 278) (OCR)"},"09136d0a2409202f":{"t":"1 Kor 1, 17-25\nČitanje Poslanice bl. Pavla apostola Korinćanima. Braćo, Krist mene nije poslao krštavati, nego propovijedati evanđelje, i to ne govorničkim nadmetanjem u riječi, da ne izgubi značenje Kristov križ. Nauka o križu je ludost za one koji propadaju, a za one koji se spašavaju, to jest za nas, Božja moć. Pisano je; Uništit ću mudrost mudrih i objaviti razumnost razumnih. Gdje je mudrac? Gdje književnik? Gdje li istraživatelj ovoga vijeka? Nije li Bog pokazao da je mudrost ovoga svijeta luda? Zato što svijet po svojoj mudrosti nije upoznao Boga u njegovoj mudrosti, po volji je Bogu da one koji vjeruju spasi propovijedanjem te ludosti. Dok Židovi zahtijevaju čudesa, a Grci traže mudrost, mi pak propovijedamo raspetoga Krista što je za Zidove sablazan a za nevjernike ludost, dok je za pozvane, bili oni Židovi ih* Grci, Krist je Božja moć i Božja mudrost. Što je ludo kod Boga, mudrije je od ljudi, i ono slabo kod Boga, jače je od ljudi.","v":"∅ → enim","kn":"Čitanje poslanice bi. Pavla apostola Korinćanma (I. 1, 17-25). Braćo! Krist me nije poslao da, krstim, nego da propovijedam evanđelje, ne u mudrim riječima,. da ne izgubi silu križ Kristov, jer je nauka križa ludost onima, koji propadaju, a onima, kop se spašavaju, to jest nama, moć je Božja. Jer ovak je pisano: Uništit ću mudrost mudrih i odbacit cu pamet pametnih. Gdje je mudrac? Gdje Gdje istraživalac ovoga vijeka? Nije li Bog P kazao, da je luda mudrost ovoga svijeta? Zato sto .svijet ni u Božjoj mudrosti ni po svojoj mudros i nije uipoznao Boga, svidjelo se Bogu, da on^ oj vjeruju spasi po ludosti propovijedanja. Dok Zidovi idu za čudesima, a Grci traže mudrost m, prop^ vijedamo raspetoga Krista, što je za Židove sablazan, a za Grke ludost, a za one Židove i Grke koji su pozvani. Krist je Božja moć i Božja • Jer što izgleda ludo od Boga, mudrije je -od ljudi, i ono slabo od Boga, jače je od ljudi.","knRef":"Kniewald 1942, str. 554–555 (snimka 278) (OCR)"},"01a54c5ad63a96af":{"t":"2 Kor 5, 15, Rim 8, 17\n<i>Aleluja</i>, <i>aleluja</i>.\n(2 Kor 5, 15) Krist je umro za sve. Stoga treba da svi koji žive više ne žive samima sebi nego onome koji je za njih umro i uskrsnuo. <i>Aleluja</i>.\n(Rim 8, 17) Ako smo sinovi, onda smo i baštinici. Doista smo baštinici Božji i subaštinici Kristovi. Ako s njim trpimo, bit ćemo s njim i proslavljeni. <i>Aleluja</i>.","kn":"Aleluja, aleluja (II. K.or. 5, 15). Za sve je umro Krist da, koji žive, ne žive više sami sebi, nego -onomu, koji je za njih umro 1 uskrsnuo. Aleluja, (Rim. 8, 17) A-ko smo djeca, i baštini-ci ,smo, baštinici naime Božji, a su'baštinici Kristovi, jer alM s njim trpimo, s njim ćemo se i proslaviti, aleluja.","knRef":"Kniewald 1942, str. 554–555 (snimka 278) (OCR)"},"22b5143a1c0cf786":{"t":"Lk 10, 1-9\nSlijedi sveto Evanđelje po Luki. U ono vrijeme odredi Gospodin i drugu sedamdeset i dvojicu i posla ih dva po dva pred sobom u svaki grad i mjesto kamo je sam kanio doći. I govorio im je: Žetva je velika, a radnika je malo. Zato molite gospodara žetve da pošalje radnike u svoju žetvu. Idite: Evo, ja vas šaljem kao janjce među vukove. Ne nosite ni kese ni torbe ni obuće i nikoga ne pozdravljajte na putu. U kojugod kuću uđete, kažite najprije: Mir ovoj kući! I ako tko ondje bude dostojan mira, ostat će na njemu vaš mir, ako ne bude, vratit će se k vama. Ostanite u onoj kući, jedite i pijte što imaju jer radnik zaslužuje svoju plaću. Ne prelazite iz kuće u kuću. I u kojigod grad uđete i prime vas, jedite, što postave pred vas. I liječite bolesne koji su u njemu, i kažite im: Približilo vam se kraljevstvo Božje!","kn":"t Slijedi sv. evanđelje Po Luki (10, 1-9). U ono vrijeme odredi Gospodin i drugu sedamdeset i dvojicu 1 posla ih dva po dva pred sobom u svaki gnad i mjesto, kamo je sam kanio doći. I govorio, im je: Žetva je velika, a radnika je malo. Zato molite gospodara žetve, da pošalje radnike u svoju žetvu. Idite: Evo, ja vas šaljem kao janjce među vukove. Ne nosite ni kese ni torbe ni obuće, i nikoga ne pozdravljajte na putu. U kojugod kuću uđete, kažite najprije: Mir ovoj kući! I ako tko ondje bude dostojan mira, ostat će na njemu vaš mir, ako ne bude, vratit će se k vama. Ostanite u onoj kući, jedite i pijte, što imaju, jer radnik zaslužuje svoju plaću.. Ne prelazite iz kuće u kuću. I u kojigođ grad uđete 1 prime vas, jedite, što se. donese pred vas. I liječite bolesne, koji su u njemu, i kažite im: Približilo vam se kraljevstvo Božje! .","knRef":"Kniewald 1942, str. 734–735 (snimka 368) (OCR)"},"e7fe4f9727bdec55":{"t":"Ef 5, 2\nNeka vaš život bude ispunjen onakvom ljubavlju kakvom je Krist sve nas ljubio i predao sebe za nas kao prinos i žrtvu Bogu na ugodni miris. <i>Aleluja</i>.","kn":"(Ef. 5, 2). Živite u ljubavi, ka-o što je i Krist ljubio nas i predao sebe za nas kao prinos i žrtvu Bogu na slatki miris, aleluja.","knRef":"Kniewald 1942, str. 554–555 (snimka 278) (OCR)"},"3a1c580dcf71eeef":{"t":"Ove tajne muke i smrti tvoje dale nam, Gospodine, nebeski žar kojim je sveti Pavao, dok ih je prinosio, tebi prikazivao svoje tijelo kao žrtvu živu, svetu i ugodnu:\n<i>koji živiš i kraljuješ s Bogom Ocem u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":", Dale ,nam, Gospodine, ove nebeske tajne žar Tvoje muke i smrti, kojim je .sv. Pavao, prikazujući ih, prinio Tebi svoje tijelo kao žrtvu živu, svetu i Tebi prijatnu, koji živiš i kraljuješ ...","knRef":"Kniewald 1942, str. 556–557 (snimka 279) (OCR)"},"1a0a565aa39e4fe3":{"t":"Uistinu je dostojno i pravedno, pravo i spasonosno da tebe, Gospodine, u svako doba, a osobito <i>u ovo</i> svečanije slavimo, kad je Krist žrtvovan, naše vazmeno Janje. On je naime pravo janje koje oduze grijehe svijeta. Svojom smrću on je uništio našu smrt i svojim uskrsnućem obnovio naš život. – I stoga s anđelima i arkanđelima, s prijestoljima i gospodstvima i sa svom nebeskom vojskom pjesmu tvoje slave pjevamo bez prestanka:","kn":"j Uistinu je dostojno i pravedno, pravo i spaso- I doba, ali osobito svečano na - današnji dan, (u ovo vrijeme), kad je žrtvovano naše vazmeno Janje, I Isukrst; jer On je pravo janje, koje je uzelo grijehe : svojim je uskrsnućem obnovio naš ž^vot. Zato pje- I vamo pjesmu Tvoje slave s anđelima i s arkanđe lima, s. prijestolima i s gospodstvima i sa svom silom nebeske vojske govoreći bez prestanka:","knRef":"Kniewald 1942, str. 20–21 (snimka 11) (OCR)"},"865b1e6adf8afe4f":{"t":"1 Pt 4, 13\nRadujte se što sudjelujete u mukama Kristovim, a kad se objavi njegova slava, radost će vaša biti beskrajna. <i>Aleluja</i>.","kn":"(I. Petr. 4. 14). Radujte se, što ste zajedničari patnja Kristovih, da se radujete klikujući i onda, kad se objavi slava njegova, aleluja.","knRef":"Kniewald 1942, str. 556–557 (snimka 279) (OCR)"},"17fac6103fc1eb90":{"t":"<i>Pomolimo se</i>.\nPrimili smo. Gospodine, božansko o–l tajstvo, neprestanu uspomenu tvoje neizmjerne ljubavi : daj, molimo, da po zaslugama i nasljedovanju svetoga Pavla crpimo iz tvojih izvora vodu koja teče u vječni život i da zadržimo vladanjem i životom tvoju muku utisnutu u našim srcima:\n<i>koji živiš i kraljuješ s Bogom Ocem u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Primivši, Gospodine, božansku tajnu, vjekoviti spomen Tvoje neizmjerne ljubavi, molimo Te, podaj, da zaslugama i nasljedovanjem sv. Pavla iz Tvojih izvora crpemo vodu, što teče u život vječni i u svojim srcima zadržimo utisnutu Tvoju muku, izraženu vladanjem i životom, koji živiš i kraljuješ ...","knRef":"Kniewald 1942, str. 556–557 (snimka 279) (OCR)"}}});
